+		if (!S_ISLNK(sctx->cur_inode_mode)) {
 			need_chmod = true;
+			need_fileattr = true;
+		}
 		if (sctx->cur_inode_next_write_offset == sctx->cur_inode_size)
 			need_truncate = false;
 	} else {
